package com.bank.sim;

import java.util.ArrayList;
import java.util.List;
import java.util.logging.Logger;

public class BatchOrderSimulator {

    private static final Logger log = Logger.getLogger(BatchOrderSimulator.class.getName());

    public List<List<Integer>> permute(int[] batches) {
        List<List<Integer>> result = new ArrayList<>();
        backtrack(batches, new boolean[batches.length], new ArrayList<>(), result);
        log.info(() -> "Generated " + result.size() + " run orders");
        return result;
    }

    private void backtrack(int[] nums, boolean[] used, List<Integer> path, List<List<Integer>> result) {
        if (path.size() == nums.length) {
            result.add(new ArrayList<>(path));         // a complete ordering
            return;
        }
        for (int i = 0; i < nums.length; i++) {
            if (used[i]) continue;                     // skip already-placed batch
            used[i] = true; path.add(nums[i]);
            backtrack(nums, used, path, result);
            path.remove(path.size() - 1); used[i] = false; // undo
        }
    }
}
