package com.bank.sim;

import java.util.logging.ConsoleHandler;
import java.util.logging.Logger;

public class PermutationsDemo {

    private static final Logger log = Logger.getLogger(PermutationsDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (var h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler handler = new ConsoleHandler();
        handler.setFormatter(new BankLogFormatter());
        root.addHandler(handler);
    }

    public static void main(String[] args) {
        log.info("National Bank of India — Settlement Batch Order Simulator");
        int[] batches = {1, 2, 3}; // three distinct EOD batches
        BatchOrderSimulator sim = new BatchOrderSimulator();
        sim.permute(batches).forEach(order -> log.info("Run order: " + order));
    }
}
